code.javascript:
function firstUniqChar(s) {
  for (let i = 0; i < s.length; i++) {
    let duplicated = false;
    for (let j = 0; j < s.length; j++) {
      if (j !== i && s[j] === s[i]) { duplicated = true; break; }
    }
    if (!duplicated) return i;
  }
  return -1;
}

