function frequencySort(s) {
  const counts = new Map();
  for (const ch of s) counts.set(ch, (counts.get(ch) || 0) + 1);
  let out = "";
  while (counts.size > 0) {
    let bestChar = null;
    let bestCount = -1;
    for (const [ch, n] of counts) {
      if (n > bestCount || (n === bestCount && ch < bestChar)) {
        bestChar = ch;
        bestCount = n;
      }
    }
    out += bestChar.repeat(bestCount);
    counts.delete(bestChar);
  }
  return out;
}

code.python:
def frequency_sort(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    out = []
    while counts:
        best_char = None
        best_count = -1
        for ch, n in counts.items():
            if n > best_count or (n == best_count and ch < best_char):
                best_char = ch
                best_count = n
        out.append(best_char * best_count)
        del counts[best_char]
    return "".join(out)

